"""Mock tessaro_feeds for testing certpin."""

import hashlib


def fingerprint(cert_der: bytes) -> str:
    """Compute SHA-256 fingerprint of a DER certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Simple pinned certificate fingerprint store."""

    # Pre-computed fingerprints keyed by hostname
    _pins = {
        "feeds.tessaro.net": None,  # will be set after fingerprint is computed
    }

    def __init__(self):
        self._pins = dict(PinStore._pins)

    @classmethod
    def load(cls):
        """Load the pin store from the default configuration."""
        return cls()

    def matches(self, host: str, fp: str) -> bool:
        """Return True if `fp` matches the pinned fingerprint for `host`."""
        return self._pins.get(host) == fp

    @classmethod
    def pin(cls, host: str, fp: str):
        """Pin a fingerprint for a host."""
        cls._pins[host] = fp
